package com.fasterxml.jackson.core.io;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for com.fasterxml.jackson.core.io.NumberInput.parseBigDecimal
 */
public class NumberInput_parseBigDecimal_TriageGen2Test {

    @Test
    public void testParseBigDecimal_ValidInteger() throws NumberFormatException {
        String input = "123";
        BigDecimal expected = new BigDecimal("123");
        BigDecimal actual = NumberInput.parseBigDecimal(input);
        assertEquals("Should correctly parse a simple integer string", expected, actual);
    }


















}

